From ba440e86b441b0141f1b3b307aacc092b589a91d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:36:12 +0100
Subject: [PATCH] wallpapers/image: list symlinks to images inside wallpaper
 packages

The finder skips images inside wallpaper packages, but it checked where a
symlink points instead of where the link itself is, so links to package
images were missing from the slideshow. Check the link's own path instead.

BUG: 479296
---
 wallpapers/image/plugin/finder/imagefinder.cpp | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/wallpapers/image/plugin/finder/imagefinder.cpp b/wallpapers/image/plugin/finder/imagefinder.cpp
index 4e5bf53e6c..8064285eec 100644
--- a/wallpapers/image/plugin/finder/imagefinder.cpp
+++ b/wallpapers/image/plugin/finder/imagefinder.cpp
@@ -55,7 +55,7 @@ QStringList ImageWallpaper::findAll(const QStringList &searchPaths)
             const QFileInfo realwp(findSymlinkTarget(wp));

             if (realwp.isFile()) {
-                if (filterCondition(realwp) && !realwp.isSymLink() && isAcceptableSuffix(realwp.suffix())) {
+                if (filterCondition(wp) && !realwp.isSymLink() && isAcceptableSuffix(realwp.suffix())) {
                     images.append(realwp.filePath());
                 }
             } else if (realwp.isDir() && !realwp.absoluteFilePath().contains(QLatin1String("contents/images"))) {
